// spec: specs/nav-menu-a11y.md (2.2–2.4) · кейсы: .qa/tests/nav-menu-a11y/NAV-A11Y-04.md, NAV-A11Y-05.md, NAV-A11Y-06.md
// seed: tests/seed.spec.ts (гость) · прод, только чтение: не-GET обрываются, SW выключен. WhatsApp не нажимается.
// Источник: комментарий PR #200 «מוסתרים, ואחרי הסגירה הם חוזרים»; #96f55c (44×44); #062b41 (WhatsApp над נגישות,
// тот же левый край; при открытом виджете נגישות WhatsApp скрыт); F-27 (кнопка נגישות работает).
import { test, expect, Page } from '@playwright/test';
import { prepareReadOnly, dismissPopups, waitReady, LOAD } from '../html-rtl-dir/rtl-dir.helpers';
import { whatsapp, a11yButton, menuButton, menuDialog, openMenu, expectFloatingHidden, expectFloatingBack } from './floating.helpers';

test.use({ serviceWorkers: 'block' });

async function openHome(page: Page, context: import('@playwright/test').BrowserContext) {
  await prepareReadOnly(context);
  await dismissPopups(page);
  await page.goto('/');
  await waitReady(page, 'home');
  await expectFloatingBack(page, '/ до открытия меню');
}

const CLOSERS: { name: string; close: (page: Page) => Promise<void>; navigates?: boolean }[] = [
  { name: '✕', close: (page) => menuDialog(page).getByRole('button', { name: /^(Close|סגור)$/ }).click() },
  { name: 'фон', close: (page) => page.mouse.click(8, 200) }, // затемнённый фон слева от меню (меню открывается справа)
  { name: 'Esc', close: (page) => page.keyboard.press('Escape') },
  {
    name: 'пункт меню',
    navigates: true,
    close: async (page) => {
      await menuDialog(page).getByRole('link', { name: 'מחשבון רכישת עסק' }).click();
      await page.waitForURL(/\/calculator/);
    },
  },
];

test.describe('После закрытия мобильного меню плавающие WhatsApp и נגישות возвращаются', () => {
  for (const c of CLOSERS) {
    test(`Закрытие меню ${c.name}: плавающие WhatsApp и נגישות вернулись, 44×44, получают касание #0651d2 @mobile @prod-safe`, async ({ page, context }) => {
      await openHome(page, context);
      await openMenu(page);
      await expectFloatingHidden(page, 'меню открыто');

      await c.close(page);
      await expect(menuDialog(page), `закрыто (${c.name})`).toBeHidden(LOAD);
      if (c.navigates) await waitReady(page, 'calculator');
      else await expect(menuButton(page), 'aria-expanded после закрытия').toHaveAttribute('aria-expanded', 'false');
      await expectFloatingBack(page, `после закрытия (${c.name})`);
    });
  }

  test('Три цикла открыть/закрыть меню — плавающие кнопки каждый раз скрываются и возвращаются #0651d2 @mobile @prod-safe', async ({ page, context }) => {
    await openHome(page, context);
    for (let i = 1; i <= 3; i++) {
      const menu = await openMenu(page);
      await expectFloatingHidden(page, `цикл ${i}, меню открыто`);
      await menu.getByRole('button', { name: /^(Close|סגור)$/ }).click();
      await expect(menuDialog(page), `цикл ${i}: меню закрыто`).toBeHidden(LOAD);
      await expectFloatingBack(page, `цикл ${i}, после ✕`);
    }
  });

  test('Виджет «תפריט נגישות» открыт — плавающий WhatsApp скрыт, после ✕ возвращается (регресс #062b41) #0651d2 @mobile @prod-safe', async ({ page, context }) => {
    await openHome(page, context);
    await a11yButton(page).click();
    const title = page.getByRole('heading', { name: 'תפריט נגישות', exact: true });
    await expect(title, 'открыт виджет «תפריט נגישות»').toBeVisible(LOAD);
    await expect(whatsapp(page), 'при открытом виджете WhatsApp скрыт').toBeHidden();

    // ✕ — в шапке виджета рядом с заголовком; настройки виджета не трогаем.
    await title.locator('xpath=..').getByRole('button').first().click();
    await expect(title, 'виджет закрыт').toBeHidden(LOAD);
    await expectFloatingBack(page, 'после закрытия виджета');
  });
});
